CREATE TABLE warehouses(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_warehouse_tenant_code UNIQUE(tenant_id,code));
CREATE TABLE warehouse_locations(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,warehouse_id UUID NOT NULL REFERENCES warehouses(id),code VARCHAR(64) NOT NULL,CONSTRAINT uq_location_tenant_warehouse_code UNIQUE(tenant_id,warehouse_id,code));
CREATE TABLE inventory(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,product_id UUID NOT NULL,warehouse_location_id UUID NOT NULL REFERENCES warehouse_locations(id),on_hand NUMERIC(19,4) NOT NULL CHECK(on_hand>=0),reserved NUMERIC(19,4) NOT NULL CHECK(reserved>=0),committed NUMERIC(19,4) NOT NULL CHECK(committed>=0),updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_inventory_tenant_product_location UNIQUE(tenant_id,product_id,warehouse_location_id));
CREATE TABLE reservations(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,order_id UUID NOT NULL,reservation_reference VARCHAR(128) NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_reservation_tenant_reference UNIQUE(tenant_id,reservation_reference));
CREATE TABLE reservation_items(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,reservation_id UUID NOT NULL REFERENCES reservations(id),inventory_id UUID NOT NULL REFERENCES inventory(id),quantity NUMERIC(19,4) NOT NULL CHECK(quantity>0));
CREATE INDEX idx_inventory_tenant_product ON inventory(tenant_id,product_id);CREATE INDEX idx_reservations_tenant_order ON reservations(tenant_id,order_id);CREATE INDEX idx_reservation_items_tenant_reservation ON reservation_items(tenant_id,reservation_id);
